[{"order":1,"type":"heading","text":"Angular Component Lifecycle Hooks"},{"order":2,"type":"paragraph","text":"Angular components have a lifecycle, a series of events that occur from the moment the component is created until it is destroyed. Angular provides lifecycle hooks, which are methods that you can implement in your component class to tap into these events and perform custom logic."},{"order":3,"type":"subheading","text":"Common Lifecycle Hooks"},{"order":4,"type":"bullet_point","text":"ngOnChanges: Called before `ngOnInit()` and whenever one or more data-bound input properties change. Receives a `SimpleChanges` object containing the current and previous values of the changed properties."},{"order":5,"type":"bullet_point","text":"ngOnInit: Called once the component has been initialized. This is a good place to perform initialization logic, such as fetching data or setting up subscriptions."},{"order":6,"type":"bullet_point","text":"ngDoCheck: Called during every change detection run. Allows you to implement your own change detection logic. Use sparingly as it can impact performance."},{"order":7,"type":"bullet_point","text":"ngAfterContentInit: Called after Angular projects external content into the component's view. This is called only once when the component is initialized."},{"order":8,"type":"bullet_point","text":"ngAfterContentChecked: Called after Angular checks the content projected into the component. This is called after `ngAfterContentInit()` and every subsequent change detection run."},{"order":9,"type":"bullet_point","text":"ngAfterViewInit: Called after the component's view (and child views) has been fully initialized. This is called only once when the component is initialized."},{"order":10,"type":"bullet_point","text":"ngAfterViewChecked: Called after Angular checks the component's view (and child views). This is called after `ngAfterViewInit()` and every subsequent change detection run."},{"order":11,"type":"bullet_point","text":"ngOnDestroy: Called just before Angular destroys the component. This is the place to unsubscribe from observables and detach event handlers to avoid memory leaks."},{"order":12,"type":"subheading","text":"Example: Using ngOnInit and ngOnDestroy"},{"order":13,"type":"paragraph","text":"This example demonstrates how to use `ngOnInit` to fetch data and `ngOnDestroy` to unsubscribe from an observable."},{"order":14,"type":"code","text":"import { Component, OnInit, OnDestroy } from '@angular/core';
import { Subscription } from 'rxjs';
import { DataService } from './data.service';

@Component({
  selector: 'app-my-component',
  template: '<p>{{ data }}</p>'
})
export class MyComponent implements OnInit, OnDestroy {
  data: string;
  private dataSubscription: Subscription;

  constructor(private dataService: DataService) { }

  ngOnInit() {
    this.dataSubscription = this.dataService.getData().subscribe(data => {
      this.data = data;
    });
  }

  ngOnDestroy() {
    if (this.dataSubscription) {
      this.dataSubscription.unsubscribe();
    }
  }
}"},{"order":15,"type":"subheading","text":"Example: Using ngOnChanges"},{"order":16,"type":"paragraph","text":"This example demonstrates how to use `ngOnChanges` to react to changes in input properties."},{"order":17,"type":"code","text":"import { Component, OnChanges, Input, SimpleChanges } from '@angular/core';

@Component({
  selector: 'app-change-component',
  template: '<p>Previous Value: {{ previousValue }}</p><p>Current Value: {{ currentValue }}</p>'
})
export class ChangeComponent implements OnChanges {
  @Input() myInput: string;
  previousValue: string;
  currentValue: string;

  ngOnChanges(changes: SimpleChanges) {
    if (changes.myInput) {
      this.previousValue = changes.myInput.previousValue;
      this.currentValue = changes.myInput.currentValue;
    }
  }
}"},{"order":18,"type":"paragraph","text":"In the above example, `changes` is a `SimpleChanges` object that contains information about the changes to the `myInput` property.  You can access the previous and current values using `changes.myInput.previousValue` and `changes.myInput.currentValue` respectively."},{"order":19,"type":"subheading","text":"Best Practices"},{"order":20,"type":"bullet_point","text":"Avoid complex logic in `ngDoCheck` as it runs on every change detection cycle and can impact performance."},{"order":21,"type":"bullet_point","text":"Always unsubscribe from observables in `ngOnDestroy` to prevent memory leaks."},{"order":22,"type":"bullet_point","text":"Use lifecycle hooks appropriately to manage component state and resources effectively."}]
